#include <iostream>
#include <vector>
#include <cctype>

int readInt() {
    int result = 0;
    char b;
    // Skip whitespace
    do {
        b = std::cin.get();
    } while (isspace(b));
    bool negative = false;
    if (b == '-') {
        negative = true;
        b = std::cin.get();
    }
    do {
        result = result * 10 + (b - '0');
        b = std::cin.get();
    } while (isdigit(b));
    return negative ? -result : result;
}

